    quests.innerHTML = `<h3>${escapeHtml(this.t("ui.quests"))}</h3>`;
    const tabs = element("div", "quest-list-tabs");
    for (const tabId of ["outstanding", "completed"]) {
      const tab = button(this.t(`ui.quests.tab.${tabId}`), () => {
        this.questListTab = tabId;
